+import { useState } from 'react';
+import copy from '../copy/en.json';
+import { ParentGate } from '../components/ParentGate';
+import { RoundButton } from '../components/RoundButton';
+import { loadProgress, saveProgress } from '../data/progress';
+
+const t = copy.grownUps.settings;
+const NAME_MAX = 20;
+
+// A reader's display name is a first name or nickname only (PARENTS.md).
+function nameError(name) {
+  const trimmed = name.trim();
+  if (!trimmed) return t.nameEmpty;
+  if (trimmed.includes('@')) return t.nameNotEmail;
+  if (trimmed.length > NAME_MAX) return t.nameTooLong.replace('{max}', NAME_MAX);
+  return null;
+}
+
+const styles = {
+  main: {
+    minHeight: '100dvh',
+    boxSizing: 'border-box',
+    padding: 'var(--sprout-gap)',
+    background: 'var(--sprout-cream)',
+    color: 'var(--sprout-ink)',
+    fontFamily: 'var(--sprout-font)',
+    fontSize: 'var(--sprout-text-body)',
+    lineHeight: 'var(--sprout-line)',
+  },
+  form: { display: 'grid', gap: 'var(--sprout-gap)', maxWidth: '36rem' },
+  fieldset: {
+    display: 'grid',
+    gap: 'calc(var(--sprout-gap) / 2)',
+    margin: 0,
+    padding: 'var(--sprout-gap)',
+    border: '2px solid var(--sprout-leaf)',
+    borderRadius: 'var(--sprout-radius-blob)',
+  },
+  legend: { fontWeight: 700, padding: '0 calc(var(--sprout-gap) / 2)' },
+  input: (invalid) => ({
+    minHeight: 'var(--sprout-tap)',
+    padding: '0 var(--sprout-gap)',
+    font: 'inherit',
+    color: 'inherit',
+    background: 'white',
+    border: `2px solid ${invalid ? 'var(--sprout-alert)' : 'var(--sprout-soil)'}`,
+    borderRadius: 'var(--sprout-radius-pill)',
+  }),
+  help: { margin: 0 },
+  error: { margin: 0, color: 'var(--sprout-alert)', fontWeight: 700 },
+  switchRow: {
+    display: 'flex',
+    alignItems: 'center',
+    gap: 'var(--sprout-gap)',
+    minHeight: 'var(--sprout-tap)',
+    cursor: 'pointer',
+  },
+  switchInput: { width: 'var(--sprout-tap)', height: 'calc(var(--sprout-tap) / 2)', accentColor: 'var(--sprout-leaf-deep)', margin: 0 },
+  actions: { display: 'flex', flexWrap: 'wrap', gap: 'var(--sprout-gap)', alignItems: 'center' },
+};
+
+const focusCss = `
+.sprout-settings :is(input, button):focus-visible { outline: none; box-shadow: var(--sprout-focus); }
+`;
+
+function SettingsForm({ onDone }) {
+  const [initial] = useState(loadProgress);
+  const [name, setName] = useState(initial.name);
+  const [reminders, setReminders] = useState(initial.reminders);
+  const [touched, setTouched] = useState(false);
+  const [saved, setSaved] = useState(false);
+
+  const error = touched ? nameError(name) : null;
+
+  function handleSubmit(event) {
+    event.preventDefault();
+    setTouched(true);
+    if (nameError(name)) {
+      setSaved(false);
+      document.getElementById('settings-name')?.focus();
+      return;
+    }
+    // Re-read so we never overwrite seeds or sprouts earned since this screen opened.
+    saveProgress({ ...loadProgress(), name: name.trim(), reminders });
+    setName(name.trim());
+    setSaved(true);
+  }
+
+  return (
+    <main className="sprout-settings" style={styles.main}>
+      <style>{focusCss}</style>
+      <h1 style={{ fontSize: 'var(--sprout-text-title)', marginTop: 0 }}>{t.title}</h1>
+
+      <form style={styles.form} onSubmit={handleSubmit} noValidate>
+        <div style={{ display: 'grid', gap: 'calc(var(--sprout-gap) / 2)' }}>
+          <label htmlFor="settings-name" style={{ fontWeight: 700 }}>{t.nameLabel}</label>
+          <input
+            id="settings-name"
+            type="text"
+            autoComplete="off"
+            autoCapitalize="words"
+            spellCheck={false}
+            value={name}
+            onChange={(e) => { setName(e.target.value); setSaved(false); }}
+            onBlur={() => setTouched(true)}
+            aria-invalid={Boolean(error)}
+            aria-describedby={error ? 'settings-name-error settings-name-help' : 'settings-name-help'}
+            style={styles.input(Boolean(error))}
+          />
+          {error && <p id="settings-name-error" style={styles.error}>{error}</p>}
+          <p id="settings-name-help" style={styles.help}>
+            {t.nameHelp.replace('{name}', name.trim() || initial.name)}
+          </p>
+        </div>
+
+        <fieldset style={styles.fieldset}>
+          <legend style={styles.legend}>{t.notificationsTitle}</legend>
+          <label style={styles.switchRow}>
+            <input
+              type="checkbox"
+              role="switch"
+              checked={reminders}
+              onChange={(e) => { setReminders(e.target.checked); setSaved(false); }}
+              aria-describedby="settings-reminders-help"
+              style={styles.switchInput}
+            />
+            <span>{t.remindersLabel}</span>
+          </label>
+          <p id="settings-reminders-help" style={styles.help}>{t.remindersHelp}</p>
+        </fieldset>
+
+        <div style={styles.actions}>
+          <RoundButton type="submit">{t.save}</RoundButton>
+          <RoundButton tone="sky" onClick={onDone}>{t.back}</RoundButton>
+        </div>
+        <p role="status" style={{ ...styles.help, minHeight: '1.5em' }}>{saved ? t.saved : ''}</p>
+      </form>
+    </main>
+  );
+}
+
+// Settings only ever open through the parental gate (PARENTS.md).
+export function SettingsScreen({ onDone }) {
+  return (
+    <ParentGate onCancel={onDone}>
+      <SettingsForm onDone={onDone} />
+    </ParentGate>
+  );
+}
