@@ -0,0 +1,135 @@
+import { useState } from 'react';
+import { Button, Checkbox, Field, Fieldset } from '../ui';
+import { PERMISSIONS, requirePermission, type Permission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationOption = { id: string; label: string; hint?: string };
+
+export type StaffSettings = {
+  displayName: string;
+  /** Keyed by NotificationOption.id; true sends an email for that event. */
+  notifications: Record<string, boolean>;
+};
+
+type Props = {
+  staff: { id: string; permissions: Permission[] };
+  settings: StaffSettings;
+  notificationOptions: NotificationOption[];
+  onSave: (settings: StaffSettings) => Promise<void>;
+};
+
+const DISPLAY_NAME_MAX = 64;
+
+function validateDisplayName(value: string): string | undefined {
+  const name = value.trim();
+  if (!name) return 'Enter a display name.';
+  if (name.length > DISPLAY_NAME_MAX) return `Display name must be ${DISPLAY_NAME_MAX} characters or fewer.`;
+  return undefined;
+}
+
+function formatUtc(iso: string) {
+  return `${iso.slice(0, 10)} ${iso.slice(11, 16)} UTC`;
+}
+
+export function Settings({ staff, settings, notificationOptions, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const [saved, setSaved] = useState(settings);
+  const [displayName, setDisplayName] = useState(settings.displayName);
+  const [notifications, setNotifications] = useState(settings.notifications);
+  const [nameError, setNameError] = useState<string>();
+  const [saveError, setSaveError] = useState<string>();
+  const [status, setStatus] = useState<string>();
+  const [saving, setSaving] = useState(false);
+
+  const changed: string[] = [];
+  if (displayName.trim() !== saved.displayName) changed.push('displayName');
+  if (notificationOptions.some((o) => Boolean(notifications[o.id]) !== Boolean(saved.notifications[o.id]))) changed.push('notifications');
+
+  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    setSaveError(undefined);
+    setStatus(undefined);
+
+    const error = validateDisplayName(displayName);
+    setNameError(error);
+    if (error) return;
+
+    if (changed.length === 0) {
+      setStatus('No changes to save.');
+      return;
+    }
+
+    const next: StaffSettings = { displayName: displayName.trim(), notifications };
+    setSaving(true);
+    try {
+      await onSave(next);
+    } catch {
+      setSaveError('Changes were not saved. Check your connection and select Save changes again.');
+      setSaving(false);
+      return;
+    }
+    setSaved(next);
+    setDisplayName(next.displayName);
+    try {
+      const entry = await audit.record({
+        actor: staff.id,
+        action: 'profile.update',
+        target: `staff:${staff.id}`,
+        reason: `Self-service settings change: ${changed.join(', ')}`,
+      });
+      setStatus(`Changes saved ${formatUtc(entry.at)}.`);
+    } catch {
+      setSaveError('Changes were saved, but the audit event was not recorded. Report this to the service desk.');
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Settings</h1>
+      <form onSubmit={handleSubmit} noValidate aria-busy={saving}>
+        <Fieldset id="profile" legend="Profile">
+          <Field
+            id="display-name"
+            label="Display name"
+            hint={`Shown to other staff. Your staff ID (${staff.id}) does not change. Maximum ${DISPLAY_NAME_MAX} characters.`}
+            error={nameError}
+          >
+            <input
+              name="displayName"
+              autoComplete="name"
+              maxLength={DISPLAY_NAME_MAX}
+              value={displayName}
+              onChange={(e) => setDisplayName(e.target.value)}
+              onBlur={() => nameError && setNameError(validateDisplayName(displayName))}
+            />
+          </Field>
+        </Fieldset>
+
+        <Fieldset id="notifications" legend="Email notifications" hint="Select the events that send an email to your work address.">
+          {notificationOptions.map((option) => (
+            <Checkbox
+              key={option.id}
+              id={`notify-${option.id}`}
+              name={`notify-${option.id}`}
+              label={option.label}
+              hint={option.hint}
+              checked={Boolean(notifications[option.id])}
+              onChange={(e) => setNotifications({ ...notifications, [option.id]: e.target.checked })}
+            />
+          ))}
+        </Fieldset>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          {saveError && <p role="alert" className="ld-field__error">{saveError}</p>}
+          <p role="status" className="ld-field__hint">{status}</p>
+        </div>
+      </form>
+    </main>
+  );
+}
