@@ -0,0 +1,73 @@
+import { SCHEMA, configFile, readConfig, readConfigFile, writeConfig } from '../config.js';
+import { emit, fail } from '../output.js';
+
+const USAGE = 'usage: logq config [ls|get <key>|set <key> <value>|unset <key>] [--json]';
+
+function checkKey(cmd, key) {
+  if (!key) fail(`config ${cmd}: missing <key>`, USAGE);
+  if (!SCHEMA[key]) fail(`config ${cmd}: unknown key: ${key}`, 'try: logq config ls');
+}
+
+function load(cmd) {
+  try {
+    return readConfigFile();
+  } catch (err) {
+    fail(`config ${cmd}: cannot read ${configFile}: ${err.message}`, 'fix or delete the file, then retry', 3);
+  }
+}
+
+function save(cmd, config) {
+  try {
+    writeConfig(config);
+  } catch (err) {
+    fail(`config ${cmd}: cannot write ${configFile}: ${err.message}`, null, 3);
+  }
+}
+
+const show = (key, value, source, json) =>
+  emit(json ? { key, value, source } : { line: `${key}=${value}` }, { json });
+
+export async function config(args) {
+  const json = args.includes('--json');
+  const [sub = 'ls', key, ...rest] = args.filter((a) => !a.startsWith('--'));
+
+  if (sub === 'ls') {
+    const set = load('ls');
+    const all = { ...readConfig(), ...set };
+    for (const k of Object.keys(SCHEMA)) show(k, all[k], k in set ? 'file' : 'default', json);
+    return 0;
+  }
+
+  if (sub === 'get') {
+    checkKey('get', key);
+    const set = load('get');
+    show(key, key in set ? set[key] : SCHEMA[key].default, key in set ? 'file' : 'default', json);
+    return 0;
+  }
+
+  if (sub === 'set') {
+    checkKey('set', key);
+    // Allow unquoted multi-word values: logq config set name Ada Lovelace
+    const raw = rest.join(' ');
+    if (!rest.length) fail(`config set: missing <value> for ${key}`, USAGE);
+    let value;
+    try {
+      value = SCHEMA[key].parse(raw);
+    } catch (err) {
+      fail(`config set: invalid value for ${key}: ${err.message}`);
+    }
+    save('set', { ...load('set'), [key]: value });
+    show(key, value, 'file', json);
+    return 0;
+  }
+
+  if (sub === 'unset') {
+    checkKey('unset', key);
+    const { [key]: _removed, ...kept } = load('unset');
+    save('unset', kept);
+    show(key, SCHEMA[key].default, 'default', json);
+    return 0;
+  }
+
+  fail(`config: unknown subcommand: ${sub}`, 'try: logq config ls');
+}
