+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { spawnSync } from 'node:child_process';
+import fs from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+
+const bin = new URL('../bin/logq.js', import.meta.url).pathname;
+
+function setup() {
+  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'logq-config-'));
+  const env = { ...process.env, XDG_CONFIG_HOME: home, XDG_DATA_HOME: home };
+  const logq = (...args) => spawnSync(process.execPath, [bin, ...args], { env, encoding: 'utf8' });
+  const file = path.join(home, 'logq', 'config.json');
+  return { logq, file };
