+import { useState } from 'react';
+import copy from '../copy/en.json';
+import { ParentGate } from '../components/ParentGate';
+import { RoundButton } from '../components/RoundButton';
+import { loadProgress, saveProgress } from '../data/progress';
+
+const NAME_MAX = 20;
+const t = copy.grownUps.settings;
+
+const fieldStyle = {
+  minHeight: 'var(--sprout-tap)',
+  borderRadius: 'var(--sprout-radius-pill)',
+  border: '2px solid var(--sprout-soil)',
+  padding: '0 var(--sprout-gap)',
+  fontSize: 'var(--sprout-text-body)',
+  fontFamily: 'inherit',
+  color: 'var(--sprout-ink)',
+  background: 'white',
+};
+
+function nameError(name) {
+  const trimmed = name.trim();
+  if (!trimmed) return t.nameEmpty;
+  if (trimmed.length > NAME_MAX) return t.nameTooLong.replace('{n}', NAME_MAX);
+  return null;
+}
+
+function SettingsForm({ onDone }) {
+  const [initial] = useState(loadProgress);
+  const [name, setName] = useState(initial.name);
+  const [reminders, setReminders] = useState(initial.reminders);
+  const [showError, setShowError] = useState(false);
+  const [status, setStatus] = useState('');
+
+  const error = nameError(name);
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    if (error) {
+      setShowError(true);
+      document.getElementById('settings-name')?.focus();
+      return;
+    }
+    const next = { ...loadProgress(), name: name.trim(), reminders };
+    saveProgress(next);
+    setName(next.name);
+    setShowError(false);
+    setStatus(t.saved);
+  }
+
+  return (
+    <main
+      aria-labelledby="settings-title"
+      style={{
+        background: 'var(--sprout-cream)',
+        color: 'var(--sprout-ink)',
+        fontFamily: 'var(--sprout-font)',
+        fontSize: 'var(--sprout-text-body)',
+        lineHeight: 'var(--sprout-line)',
+        minHeight: '100dvh',
+        padding: 'var(--sprout-gap)',
+        paddingBottom: 'calc(var(--sprout-gap) + env(safe-area-inset-bottom))',
+      }}
+    >
+      <form
+        onSubmit={handleSubmit}
+        noValidate
+        style={{ maxWidth: '36rem', margin: '0 auto', display: 'grid', gap: 'calc(var(--sprout-gap) * 1.5)' }}
+      >
+        <h1 id="settings-title" style={{ fontSize: 'var(--sprout-text-title)', margin: 0 }}>{t.title}</h1>
+
+        <div style={{ display: 'grid', gap: 'calc(var(--sprout-gap) / 2)' }}>
+          <label htmlFor="settings-name" style={{ fontWeight: 700 }}>{t.nameLabel}</label>
+          <p id="settings-name-help" style={{ margin: 0 }}>{t.nameHelp}</p>
+          <input
+            id="settings-name"
+            type="text"
+            autoComplete="off"
+            autoCapitalize="words"
+            spellCheck={false}
+            value={name}
+            onChange={(e) => { setName(e.target.value); setStatus(''); }}
+            onBlur={() => setShowError(true)}
+            aria-invalid={showError && error ? true : undefined}
+            aria-describedby={showError && error ? 'settings-name-help settings-name-error' : 'settings-name-help'}
+            style={{ ...fieldStyle, borderColor: showError && error ? 'var(--sprout-alert)' : 'var(--sprout-soil)' }}
+          />
+          {showError && error && (
+            <p id="settings-name-error" style={{ margin: 0, color: 'var(--sprout-alert)', fontWeight: 700 }}>{error}</p>
+          )}
+        </div>
+
+        <fieldset style={{ border: 0, padding: 0, margin: 0, display: 'grid', gap: 'calc(var(--sprout-gap) / 2)' }}>
+          <legend style={{ fontWeight: 700, padding: 0, marginBottom: 'calc(var(--sprout-gap) / 2)' }}>{t.notificationsTitle}</legend>
+          <label
+            htmlFor="settings-reminders"
+            style={{
+              display: 'flex',
+              alignItems: 'center',
+              gap: 'var(--sprout-gap)',
+              minHeight: 'var(--sprout-tap)',
+              padding: '0 var(--sprout-gap)',
+              borderRadius: 'var(--sprout-radius-blob)',
+              background: 'white',
+              border: '2px solid var(--sprout-soil)',
+              cursor: 'pointer',
+            }}
+          >
+            <input
+              id="settings-reminders"
+              type="checkbox"
+              role="switch"
+              checked={reminders}
+              onChange={(e) => { setReminders(e.target.checked); setStatus(''); }}
+              aria-describedby="settings-reminders-help"
+              style={{ width: 32, height: 32, accentColor: 'var(--sprout-leaf-deep)', flexShrink: 0 }}
+            />
+            <span>{t.remindersLabel}</span>
+          </label>
+          <p id="settings-reminders-help" style={{ margin: 0 }}>{copy.grownUps.goalHelp}</p>
+        </fieldset>
+
+        <div style={{ display: 'grid', gap: 'calc(var(--sprout-gap) / 2)' }}>
+          <RoundButton type="submit">{t.save}</RoundButton>
+          <p role="status" style={{ margin: 0, minHeight: '1.5em', color: 'var(--sprout-leaf-deep)', fontWeight: 700 }}>{status}</p>
+          <RoundButton tone="sky" onClick={onDone}>{t.back}</RoundButton>
+        </div>
+      </form>
+    </main>
+  );
+}
+
+export function SettingsScreen({ onDone }) {
+  return (
+    <ParentGate onCancel={onDone}>
+      <SettingsForm onDone={onDone} />
+    </ParentGate>
+  );
+}
