new file mode 100644
index 0000000..2bf0898
--- /dev/null
+++ b/src/pages/StaffSettings.tsx
@@ -0,0 +1,169 @@
+import { useState } from 'react';
+import { Field, Button } from '../ui';
+import { PERMISSIONS, requirePermission, type Permission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationPreferences = {
+  caseAssigned: boolean;
+  exportReady: boolean;
+  dailySummary: boolean;
+};
+
+export type StaffSettingsValues = {
+  displayName: string;
+  notifications: NotificationPreferences;
+};
+
+type Props = {
+  staff: { id: string; permissions: Permission[] };
+  initial: StaffSettingsValues;
+  onSave: (values: StaffSettingsValues) => Promise<void>;
+};
+
+const DISPLAY_NAME_MAX = 64;
+
+const NOTIFICATION_OPTIONS: { key: keyof NotificationPreferences; label: string; hint: string }[] = [
+  { key: 'caseAssigned', label: 'A case is assigned to me', hint: 'Sent when a case is assigned or reassigned to you.' },
+  { key: 'exportReady', label: 'An export is ready to download', hint: 'Sent when a requested export is available. Exports expire after 7 days.' },
+  { key: 'dailySummary', label: 'Daily summary of open cases', hint: 'Sent once each working day.' },
+];
+
+function validateDisplayName(value: string): string | undefined {
+  const trimmed = value.trim();
+  if (trimmed.length === 0) return 'Enter a display name.';
+  if (trimmed.length > DISPLAY_NAME_MAX) return `Display name must be ${DISPLAY_NAME_MAX} characters or fewer.`;
+  return undefined;
+}
+
+function changedFields(before: StaffSettingsValues, after: StaffSettingsValues): string[] {
+  const fields: string[] = [];
+  if (before.displayName !== after.displayName) fields.push('displayName');
+  for (const { key } of NOTIFICATION_OPTIONS) {
+    if (before.notifications[key] !== after.notifications[key]) fields.push(`notifications.${key}`);
+  }
+  return fields;
+}
+
+export function StaffSettings({ staff, initial, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const [saved, setSaved] = useState(initial);
+  const [values, setValues] = useState(initial);
+  const [nameError, setNameError] = useState<string>();
+  const [saveError, setSaveError] = useState<string>();
+  const [status, setStatus] = useState<string>('');
+  const [saving, setSaving] = useState(false);
+
+  const changes = changedFields(saved, { ...values, displayName: values.displayName.trim() });
+
+  function setNotification(key: keyof NotificationPreferences, enabled: boolean) {
+    setValues((v) => ({ ...v, notifications: { ...v.notifications, [key]: enabled } }));
+    setStatus('');
+  }
+
+  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    setSaveError(undefined);
+    setStatus('');
+
+    const error = validateDisplayName(values.displayName);
+    setNameError(error);
+    if (error) {
+      document.getElementById('settings-display-name')?.focus();
+      return;
+    }
+
+    const next: StaffSettingsValues = { ...values, displayName: values.displayName.trim() };
+    if (changes.length === 0) {
+      setStatus('No changes to save.');
+      return;
+    }
+
+    setSaving(true);
+    try {
+      requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+      await onSave(next);
+      await audit.record({
+        actor: staff.id,
+        action: 'profile.update',
+        target: staff.id,
+        reason: `Self-service settings change: ${changes.join(', ')}`,
+      });
+      setSaved(next);
+      setValues(next);
+      setStatus('Changes saved.');
+    } catch {
+      setSaveError('Changes were not saved. Check your connection and select "Save changes" again.');
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  function handleDiscard() {
+    setValues(saved);
+    setNameError(undefined);
+    setSaveError(undefined);
+    setStatus('');
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Settings</h1>
+      <form onSubmit={handleSubmit} noValidate aria-busy={saving}>
+        <section aria-labelledby="settings-profile-heading">
+          <h2 id="settings-profile-heading">Profile</h2>
+          <Field
+            id="settings-display-name"
+            label="Display name"
+            hint={`Shown to other staff in LedgerDesk. Your staff ID does not change. Maximum ${DISPLAY_NAME_MAX} characters.`}
+            error={nameError}
+          >
+            <input
+              name="displayName"
+              autoComplete="name"
+              value={values.displayName}
+              onChange={(e) => {
+                setValues((v) => ({ ...v, displayName: e.target.value }));
+                if (nameError) setNameError(validateDisplayName(e.target.value));
+                setStatus('');
+              }}
+            />
+          </Field>
+        </section>
+
+        <fieldset>
+          <legend>
+            <h2>Email notifications</h2>
+          </legend>
+          {NOTIFICATION_OPTIONS.map(({ key, label, hint }) => (
+            <Field key={key} id={`settings-notify-${key}`} label={label} hint={hint}>
+              <input
+                type="checkbox"
+                name={key}
+                checked={values.notifications[key]}
+                onChange={(e) => setNotification(key, e.target.checked)}
+              />
+            </Field>
+          ))}
+        </fieldset>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          <Button onClick={handleDiscard} disabled={saving || changes.length === 0}>
+            Discard changes
+          </Button>
+        </div>
+        {saveError && (
+          <p role="alert" className="ld-field__error">
+            {saveError}
+          </p>
+        )}
+        <p role="status" className="ld-field__hint">
+          {status}
+        </p>
+      </form>
+    </main>
+  );
+}

