@@ -0,0 +1,82 @@
+import { SETTINGS, configFile, readConfigFile, resolveConfig, writeConfig } from '../config.js';
+import { fail } from '../output.js';
+
+const KEYS = Object.keys(SETTINGS).join(', ');
+
+function load() {
+  try {
+    return resolveConfig();
+  } catch (err) {
+    if (err instanceof SyntaxError) fail(`config: cannot parse ${configFile}: ${err.message}`, 'fix or delete the file', 3);
+    if (err.code) fail(`config: cannot read ${configFile}: ${err.code}`, null, 3);
+    fail(`config: invalid environment value: ${err.message}`);
+  }
+}
+
+function checkKey(key, usage) {
+  if (!key) fail(`config: missing <key>`, `usage: ${usage}`);
+  if (!Object.hasOwn(SETTINGS, key)) fail(`config: unknown key: ${key}`, `keys: ${KEYS}`);
+}
+
+function print(key, { value, source }, json) {
+  process.stdout.write(json ? `${JSON.stringify({ key, value, source })}\n` : `${key}=${value}\n`);
+}
+
+function save(mutate) {
+  let file;
+  try {
+    file = readConfigFile();
+  } catch (err) {
+    fail(`config: cannot read ${configFile}: ${err.message}`, 'fix or delete the file', 3);
+  }
+  mutate(file);
+  try {
+    writeConfig(file);
+  } catch (err) {
+    fail(`config: cannot write ${configFile}: ${err.code ?? err.message}`, null, 3);
+  }
+}
+
+function warnIfShadowed(key) {
+  const { env } = SETTINGS[key];
+  if (process.env[env]) process.stderr.write(`logq: note: ${env} is set and overrides the config file\n`);
+}
+
+export async function config([sub, ...args]) {
+  const json = args.includes('--json');
+  const [key, ...rest] = args.filter((a) => a !== '--json');
+
+  if (sub === 'ls') {
+    for (const [k, entry] of Object.entries(load())) print(k, entry, json);
+    return 0;
+  }
+  if (sub === 'get') {
+    checkKey(key, 'logq config get [--json] <key>');
+    print(key, load()[key], json);
+    return 0;
+  }
+  if (sub === 'set') {
+    checkKey(key, 'logq config set <key> <value>');
+    if (rest.length === 0) fail('config set: missing <value>', 'usage: logq config set <key> <value>');
+    let value;
+    try {
+      value = SETTINGS[key].parse(rest.join(' '));
+    } catch (err) {
+      fail(`config set: invalid value for ${key}: ${err.message}`);
+    }
+    save((file) => { file[key] = value; });
+    warnIfShadowed(key);
+    return 0;
+  }
+  if (sub === 'unset') {
+    checkKey(key, 'logq config unset <key>');
+    save((file) => { delete file[key]; });
+    warnIfShadowed(key);
+    return 0;
+  }
+  if (sub === 'path') {
+    process.stdout.write(json ? `${JSON.stringify({ path: configFile })}\n` : `${configFile}\n`);
+    return 0;
+  }
+  fail(`config: unknown subcommand: ${sub ?? '(none)'}`, 'try: logq config ls');
+}
