+import { useState } from 'react';
+import copy from '../copy/en.json';
+import { ParentGate } from '../components/ParentGate';
+import { RoundButton } from '../components/RoundButton';
+import { loadProgress, saveProgress } from '../data/progress';
+
+const t = copy.settings;
+const NAME_MAX = 20;
+// First name or nickname only (PARENTS.md): letters, spaces, hyphens, apostrophes.
+const NAME_PATTERN = /^[\p{L}][\p{L}\p{M} '’-]*$/u;
+
+export function checkName(raw) {
+  const name = raw.trim().replace(/\s+/g, ' ');
+  if (!name) return { error: t.nameEmpty };
+  if (name.length > NAME_MAX) return { error: t.nameTooLong.replace('{n}', NAME_MAX) };
+  if (!NAME_PATTERN.test(name)) return { error: t.nameLettersOnly };
+  return { name };
+}
+
+const fieldStyle = {
+  minHeight: 'var(--sprout-tap)',
+  borderRadius: 'var(--sprout-radius-pill)',
+  fontSize: 'var(--sprout-text-body)',
+  fontFamily: 'inherit',
+  padding: '0 24px',
+  border: '3px solid var(--sprout-leaf)',
+  color: 'var(--sprout-ink)',
+  background: 'white',
+};
+
+function SettingsForm({ onDone }) {
+  const [saved, setSaved] = useState(loadProgress);
+  const [name, setName] = useState(saved.name);
+  const [reminders, setReminders] = useState(saved.reminders);
+  const [error, setError] = useState('');
+  const [status, setStatus] = useState('');
+
+  function save() {
+    const result = checkName(name);
+    if (result.error) {
+      setError(result.error);
+      setStatus('');
+      return;
+    }
+    // Re-read so we never overwrite seeds or stories earned since this screen opened.
+    const next = { ...loadProgress(), name: result.name, reminders };
+    saveProgress(next);
+    setSaved(next);
+    setName(result.name);
+    setError('');
+    setStatus(t.saved);
+  }
+
+  return (
+    <main
+      className="settings"
+      style={{
+        background: 'var(--sprout-cream)',
+        color: 'var(--sprout-ink)',
+        fontFamily: 'var(--sprout-font)',
+        fontSize: 'var(--sprout-text-body)',
+        lineHeight: 'var(--sprout-line)',
+        display: 'flex',
+        flexDirection: 'column',
+        gap: 'var(--sprout-gap)',
+        padding: 'var(--sprout-gap)',
+      }}
+    >
+      <h1 style={{ fontSize: 'var(--sprout-text-title)', margin: 0 }}>{t.title}</h1>
+
+      <section aria-labelledby="settings-name" style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
+        <label id="settings-name" htmlFor="settings-name-input" style={{ fontWeight: 700 }}>{t.nameLabel}</label>
+        <p id="settings-name-help" style={{ margin: 0 }}>{t.nameHelp}</p>
+        <input
+          id="settings-name-input"
+          type="text"
+          autoComplete="off"
+          autoCapitalize="words"
+          spellCheck={false}
+          maxLength={NAME_MAX + 10}
+          value={name}
+          onChange={(e) => { setName(e.target.value); setStatus(''); }}
+          aria-describedby={error ? 'settings-name-help settings-name-error' : 'settings-name-help'}
+          aria-invalid={Boolean(error)}
+          style={fieldStyle}
+        />
+        {error && <p id="settings-name-error" role="alert" style={{ margin: 0, color: 'var(--sprout-soil)', fontWeight: 700 }}>{error}</p>}
+      </section>
+
+      <section aria-labelledby="settings-reminders" style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
+        <h2 id="settings-reminders" style={{ fontSize: 'var(--sprout-text-body)', margin: 0 }}>{t.remindersTitle}</h2>
+        <p id="settings-reminders-help" style={{ margin: 0 }}>{t.remindersHelp}</p>
+        <RoundButton
+          role="switch"
+          aria-checked={reminders}
+          aria-describedby="settings-reminders-help"
+          tone={reminders ? 'leaf' : 'sky'}
+          onClick={() => { setReminders(!reminders); setStatus(''); }}
+        >
+          {reminders ? t.remindersOn : t.remindersOff}
+        </RoundButton>
+      </section>
+
+      <RoundButton onClick={save}>{t.save}</RoundButton>
+      <p role="status" style={{ margin: 0, minHeight: '1.5em' }}>{status}</p>
+      <RoundButton tone="sky" onClick={onDone}>{t.back}</RoundButton>
+    </main>
+  );
+}
+
+/** Grown-up settings. Always behind the parental gate (see PARENTS.md). */
+export function SettingsScreen({ onDone }) {
+  return (
+    <ParentGate onCancel={onDone}>
+      <SettingsForm onDone={onDone} />
+    </ParentGate>
+  );
+}

