@@ -0,0 +1,149 @@
+import { useState } from 'react';
+import { Button, Field } from '../ui';
+import { PERMISSIONS, requirePermission, type Permission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationPreferences = {
+  caseAssigned: boolean;
+  exportReady: boolean;
+  freezeRequested: boolean;
+  emailCopy: boolean;
+};
+
+export type StaffSettingsValues = {
+  displayName: string;
+  notifications: NotificationPreferences;
+};
+
+type Props = {
+  staff: { id: string; permissions: Permission[] };
+  initial: StaffSettingsValues;
+  onSave: (values: StaffSettingsValues) => Promise<void>;
+};
+
+const DISPLAY_NAME_MAX = 80;
+
+const NOTIFICATION_OPTIONS: { key: keyof NotificationPreferences; label: string; hint: string }[] = [
+  { key: 'caseAssigned', label: 'Case assigned to me', hint: 'A support or compliance case is assigned to you.' },
+  { key: 'exportReady', label: 'Export ready', hint: 'An export you requested is ready. Exports expire after 7 days.' },
+  { key: 'freezeRequested', label: 'Account freeze requested', hint: 'An account freeze awaits your approval.' },
+  { key: 'emailCopy', label: 'Send a copy by email', hint: 'Notifications are also sent to your work email address.' },
+];
+
+function formatUtc(iso: string) {
+  return `${iso.slice(0, 10)} ${iso.slice(11, 16)} UTC`;
+}
+
+function changedFields(before: StaffSettingsValues, after: StaffSettingsValues) {
+  const fields: string[] = [];
+  if (before.displayName !== after.displayName) fields.push('displayName');
+  for (const { key } of NOTIFICATION_OPTIONS) {
+    if (before.notifications[key] !== after.notifications[key]) fields.push(`notifications.${key}`);
+  }
+  return fields;
+}
+
+export function StaffSettings({ staff, initial, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const [saved, setSaved] = useState(initial);
+  const [values, setValues] = useState(initial);
+  const [nameError, setNameError] = useState<string>();
+  const [status, setStatus] = useState<{ kind: 'ok' | 'error'; message: string }>();
+  const [saving, setSaving] = useState(false);
+
+  const changes = changedFields(saved, { ...values, displayName: values.displayName.trim() });
+
+  function setNotification(key: keyof NotificationPreferences, checked: boolean) {
+    setValues((v) => ({ ...v, notifications: { ...v.notifications, [key]: checked } }));
+  }
+
+  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    const next = { ...values, displayName: values.displayName.trim() };
+
+    if (next.displayName.length === 0) {
+      setNameError('Enter a display name.');
+      return;
+    }
+    if (next.displayName.length > DISPLAY_NAME_MAX) {
+      setNameError(`Display name must be ${DISPLAY_NAME_MAX} characters or fewer.`);
+      return;
+    }
+    setNameError(undefined);
+    if (changes.length === 0) return;
+
+    setSaving(true);
+    setStatus(undefined);
+    try {
+      await onSave(next);
+      const entry = await audit.record({
+        actor: staff.id,
+        action: 'profile.update.self',
+        target: `staff:${staff.id}`,
+        reason: `Self-service settings change: ${changes.join(', ')}`,
+      });
+      setSaved(next);
+      setValues(next);
+      setStatus({ kind: 'ok', message: `Changes saved ${formatUtc(entry.at)}.` });
+    } catch {
+      setStatus({ kind: 'error', message: 'Changes not saved. Try again or contact the service desk.' });
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Settings</h1>
+      <form onSubmit={handleSubmit} noValidate>
+        <section aria-labelledby="settings-profile">
+          <h2 id="settings-profile">Profile</h2>
+          <Field
+            id="displayName"
+            label="Display name"
+            hint={`Shown to other staff. Maximum ${DISPLAY_NAME_MAX} characters.`}
+            error={nameError}
+          >
+            <input
+              name="displayName"
+              autoComplete="name"
+              maxLength={DISPLAY_NAME_MAX}
+              required
+              value={values.displayName}
+              onChange={(e) => setValues((v) => ({ ...v, displayName: e.target.value }))}
+            />
+          </Field>
+        </section>
+
+        <fieldset>
+          <legend>Notifications</legend>
+          {NOTIFICATION_OPTIONS.map(({ key, label, hint }) => (
+            <Field key={key} id={`notify-${key}`} label={label} hint={hint}>
+              <input
+                type="checkbox"
+                name={key}
+                checked={values.notifications[key]}
+                onChange={(e) => setNotification(key, e.target.checked)}
+              />
+            </Field>
+          ))}
+        </fieldset>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving || changes.length === 0}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          <Button onClick={() => { setValues(saved); setNameError(undefined); setStatus(undefined); }} disabled={saving || changes.length === 0}>
+            Discard changes
+          </Button>
+        </div>
+
+        <p role="status" className={status?.kind === 'ok' ? 'ld-status--ok' : undefined}>
+          {status?.kind === 'ok' ? status.message : ''}
+        </p>
+        {status?.kind === 'error' && <p role="alert" className="ld-status--error">{status.message}</p>}
+      </form>
+    </main>
+  );
+}

