+import { useState } from 'react';
+import { Button, ConfirmDialog, Field } from '../ui';
+import { PERMISSIONS, Permission, requirePermission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationPreferences = {
+  caseAssigned: boolean;
+  approvalRequested: boolean;
+  exportReady: boolean;
+  emailDigest: boolean;
+};
+
+export type StaffSettings = {
+  displayName: string;
+  notifications: NotificationPreferences;
+};
+
+type Staff = { id: string; permissions: Permission[] };
+
+type Props = {
+  staff: Staff;
+  settings: StaffSettings;
+  onSave: (settings: StaffSettings) => Promise<void>;
+};
+
+const NOTIFICATION_OPTIONS: { key: keyof NotificationPreferences; label: string; hint: string }[] = [
+  { key: 'caseAssigned', label: 'Case assigned to me', hint: 'In-app notification when a case is assigned to you.' },
+  { key: 'approvalRequested', label: 'Approval requested', hint: 'In-app notification when an action awaits your approval.' },
+  { key: 'exportReady', label: 'Export ready', hint: 'In-app notification when a requested export is available for download.' },
+  { key: 'emailDigest', label: 'Daily email summary', hint: 'One email per working day at 07:00 UTC listing open notifications.' },
+];
+
+const DISPLAY_NAME_MAX = 64;
+
+function validateDisplayName(value: string): string | undefined {
+  const trimmed = value.trim();
+  if (trimmed.length === 0) return 'Enter a display name.';
+  if (trimmed.length > DISPLAY_NAME_MAX) return `Display name must be ${DISPLAY_NAME_MAX} characters or fewer.`;
+  return undefined;
+}
+
+export function Settings({ staff, settings, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const [displayName, setDisplayName] = useState(settings.displayName);
+  const [notifications, setNotifications] = useState<NotificationPreferences>(settings.notifications);
+  const [error, setError] = useState<string>();
+  const [status, setStatus] = useState<string>();
+  const [saving, setSaving] = useState(false);
+  const [confirming, setConfirming] = useState(false);
+
+  const nameChanged = displayName.trim() !== settings.displayName;
+  const changedPreferences = NOTIFICATION_OPTIONS.filter((o) => notifications[o.key] !== settings.notifications[o.key]);
+  const hasChanges = nameChanged || changedPreferences.length > 0;
+
+  async function save() {
+    setConfirming(false);
+    setSaving(true);
+    setStatus(undefined);
+    const next: StaffSettings = { displayName: displayName.trim(), notifications };
+    try {
+      await onSave(next);
+      const target = `staff:${staff.id}`;
+      if (nameChanged) {
+        await audit.record({ actor: staff.id, action: 'profile.display_name.update', target, reason: 'Self-service settings change' });
+      }
+      if (changedPreferences.length > 0) {
+        await audit.record({
+          actor: staff.id,
+          action: 'profile.notifications.update',
+          target,
+          reason: `Self-service settings change: ${changedPreferences.map((o) => o.key).join(', ')}`,
+        });
+      }
+      setStatus(`Changes saved ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC.`);
+    } catch {
+      setStatus('Changes could not be saved. No settings were changed.');
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  function handleSubmit(event: React.FormEvent) {
+    event.preventDefault();
+    const validation = validateDisplayName(displayName);
+    setError(validation);
+    if (validation || !hasChanges) return;
+    if (nameChanged) {
+      setConfirming(true);
+    } else {
+      void save();
+    }
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Settings</h1>
+      <form onSubmit={handleSubmit} noValidate>
+        <section aria-labelledby="settings-profile">
+          <h2 id="settings-profile">Profile</h2>
+          <Field
+            id="displayName"
+            label="Display name"
+            hint={`Shown to other staff in case history and the audit trail. Maximum ${DISPLAY_NAME_MAX} characters.`}
+            error={error}
+          >
+            <input
+              name="displayName"
+              value={displayName}
+              maxLength={DISPLAY_NAME_MAX}
+              autoComplete="off"
+              onChange={(e) => setDisplayName(e.target.value)}
+            />
+          </Field>
+        </section>
+
+        <section aria-labelledby="settings-notifications">
+          <h2 id="settings-notifications">Notification preferences</h2>
+          <fieldset className="ld-fieldset">
+            <legend>Notify me about</legend>
+            {NOTIFICATION_OPTIONS.map((o) => (
+              <Field key={o.key} id={`notify-${o.key}`} label={o.label} hint={o.hint}>
+                <input
+                  type="checkbox"
+                  name={o.key}
+                  checked={notifications[o.key]}
+                  onChange={(e) => setNotifications({ ...notifications, [o.key]: e.target.checked })}
+                />
+              </Field>
+            ))}
+          </fieldset>
+        </section>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving || !hasChanges}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          <Button
+            disabled={saving || !hasChanges}
+            onClick={() => {
+              setDisplayName(settings.displayName);
+              setNotifications(settings.notifications);
+              setError(undefined);
+            }}
+          >
+            Discard changes
+          </Button>
+        </div>
+        <p role="status" aria-live="polite">{status}</p>
+      </form>
+
+      {confirming && (
+        <ConfirmDialog
+          title="Change display name"
+          consequence={`Your display name will change from "${settings.displayName}" to "${displayName.trim()}". All staff will see the new name in case history and the audit trail. The change is recorded in the audit trail.`}
+          confirmLabel="Change display name"
+          onConfirm={() => void save()}
+          onCancel={() => setConfirming(false)}
+        />
+      )}
+    </main>
+  );
+}
